<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\Province; use Illuminate\Http\Request;
class ProvinceController extends Controller { public function index(){return view('admin.provinces.index',['provinces'=>Province::withCount('cities')->orderBy('name')->paginate(20)]);} public function create(){return view('admin.provinces.form',['province'=>new Province]);} public function store(Request $r){$d=$r->validate(['name'=>'required|max:255']);Province::create($d);return redirect()->route('admin.provinces.index')->with('success','استان ایجاد شد.');} public function edit(Province $province){return view('admin.provinces.form',compact('province'));} public function update(Request $r,Province $province){$d=$r->validate(['name'=>'required|max:255']);$province->update($d);return redirect()->route('admin.provinces.index')->with('success','استان ویرایش شد.');} public function destroy(Province $province){if($province->ads()->exists())return back()->with('error','این استان آگهی دارد و قابل حذف نیست.');$province->delete();return back()->with('success','حذف شد.');} }
